// SearchService: orchestrates unified search across repos, checkpoints, commits, and PRs.
// All full-text and semantic search goes through a single Turbopuffer query per org namespace.
// Tier-based pipeline: tier 0 (full keyword match), tier 1 (partial + top ANN, Cohere reranked),
// tier 2 (remaining ANN, capped).

import type { PostHog } from "posthog-node"

import { getAccessibleReposByUser, searchReposByUser } from "./planetscale/repos"
import {
  getCheckpointsByIdsGlobal,
  getCommitsByShasGlobal,
  getPRsByGithubIdsGlobal,
} from "./planetscale/search-queries"
import { isFeatureEnabled } from "./posthog"
import { rerankTier1 } from "./search-reranker"
import type {
  SearchMatchType,
  SearchResult,
  SearchResponse,
  SearchParams,
  SearchTier,
  CheckpointResult,
  CommitResult,
  PRResult,
} from "./search-types"
import type { UnifiedSearchRow } from "./turbopuffer"
import { embedQueryVector, searchChunksOrg } from "./turbopuffer"

export type { SearchResult, SearchResponse, SearchParams }

// Max concurrent org namespace queries
const ORG_QUERY_CONCURRENCY = 5

// Tier pipeline constants
const MAX_TIER2 = 15 // cap on tier 2 results

// Check if the full query phrase appears in any of the Turbopuffer text fields.
// For single-word queries, this checks for the word. For multi-word, checks the
// exact phrase in order.
function isFullQueryMatch(query: string, hit: UnifiedSearchRow): boolean {
  const q = query.toLowerCase()
  for (const text of [hit.title_text, hit.meta_text, hit.chunk_text]) {
    if (text && text.toLowerCase().includes(q)) return true
  }
  return false
}

// Assign tier and matchType from Turbopuffer hit data
function assignHitTier(
  query: string,
  hit: UnifiedSearchRow,
): { tier: SearchTier; matchType: SearchMatchType } {
  let tier: SearchTier
  if (hit.bm25Score !== null && isFullQueryMatch(query, hit)) {
    tier = 0
  } else if (hit.bm25Score !== null) {
    tier = 1 // BM25 matched but only partial
  } else {
    tier = 2 // ANN-only, will be promoted to tier 1 or capped later
  }

  const matchType: SearchMatchType =
    hit.bm25Score !== null && hit.annScore !== null
      ? "both"
      : hit.bm25Score !== null
        ? "keyword"
        : "semantic"

  return { tier, matchType }
}

// Apply a small recency boost to BM25 scores (higher = better).
// Skipped for ANN-only results where lower cosine distance = better.
function applyRecencyBoost(score: number, createdAt: string, isAnnOnly: boolean): number {
  if (isAnnOnly || !createdAt) return score
  const ageDays = (Date.now() - new Date(createdAt).getTime()) / (1000 * 60 * 60 * 24)
  return score * (1.0 + 0.1 * Math.max(0, 1 - ageDays / 30))
}

// ─── SearchService ────────────────────────────────────────────────────────────

export class SearchService {
  constructor(
    private readonly db: any,
    private readonly turbopufferApiKey: string | undefined,
    private readonly openaiApiKey: string | undefined,
    private readonly semanticSearchEnabled: boolean,
    private readonly cache?: KVNamespace,
    private readonly posthog?: PostHog | null,
    private readonly cohereApiKey?: string,
    private readonly skipFeatureFlags?: boolean,
  ) {}

  async search(userId: string, params: SearchParams): Promise<SearchResponse> {
    const totalStart = Date.now()
    const { types = ["repos", "checkpoints", "commits", "prs"] } = params
    const allResults: SearchResult[] = []

    let embedding_ms: number | null = null
    let vector_ms: number | null = null
    let rerank_ms: number | null = null
    let reranked: boolean | undefined

    if (types.includes("repos")) {
      const repos = await this.searchRepos(userId, params)
      allResults.push(...repos)
    }

    // Unified search covers checkpoints, commits, and PRs via Turbopuffer
    const searchTypes = types.filter((t) => t !== "repos")
    if (searchTypes.length > 0 && this.semanticSearchEnabled) {
      const embedStart = Date.now()
      const queryVector = await embedQueryVector(this.openaiApiKey!, params.q)
      embedding_ms = Date.now() - embedStart

      const vectorStart = Date.now()
      const results = await this.searchUnified(userId, params, queryVector, searchTypes)
      vector_ms = Date.now() - vectorStart
      allResults.push(...results)
    }

    // Separate into tiers
    const tier0: SearchResult[] = []
    const tier1: SearchResult[] = []
    let tier2: SearchResult[] = []
    const repoResults: SearchResult[] = []

    for (const r of allResults) {
      if (r.type === "repo") {
        repoResults.push(r)
        continue
      }
      if (r.searchMeta.tier === 0) tier0.push(r)
      else if (r.searchMeta.tier === 1) tier1.push(r)
      else tier2.push(r)
    }

    // Tier 0: sort by bm25Score desc (no rerank)
    tier0.sort((a, b) => (b.searchMeta.bm25Score ?? 0) - (a.searchMeta.bm25Score ?? 0))

    // Cohere relevance threshold: 0.3 baseline, may tighten later once we
    // have more data on score distributions.
    const hasKeywordMatches = tier0.length > 0
    const minRelevance = hasKeywordMatches ? 0.3 : 0.2

    // Tier 1: Cohere rerank with relevance threshold (BM25/hybrid results only)
    if (this.cohereApiKey && tier1.length > 0) {
      const rerankStart = Date.now()
      const rerankOutput = await rerankTier1(
        this.cohereApiKey,
        params.q,
        tier1,
        minRelevance,
        this.cache,
      )
      rerank_ms = Date.now() - rerankStart
      reranked = rerankOutput.reranked
      tier1.splice(0, tier1.length, ...rerankOutput.results)
    }

    // Append top 10% of ANN-only results (tier 2) after Cohere-reranked tier 1.
    // This prevents semantic-only results from being ranked above keyword matches
    // by the reranker when they lack sufficient context.
    // Guard on cohereApiKey: without Cohere, tier 1 may be empty and we'd
    // discard remaining tier 2 results by making tier1 non-empty.
    let promoted: SearchResult[] = []
    if (this.cohereApiKey && tier2.length > 0) {
      tier2.sort((a, b) => a.searchMeta.score - b.searchMeta.score)
      const promotionCount = Math.max(1, Math.ceil(tier2.length * 0.1))
      promoted = tier2.splice(0, promotionCount)
      tier1.push(...promoted)
    }

    // Tier 2: only show when tier 0+1 are empty (nothing relevant found).
    if (tier0.length > 0 || tier1.length > 0) {
      tier2 = []
    } else {
      tier2.unshift(...promoted)
      tier2.sort(
        (a, b) =>
          (a.searchMeta.annScore ?? a.searchMeta.score) -
          (b.searchMeta.annScore ?? b.searchMeta.score),
      )
      tier2.splice(MAX_TIER2)
    }

    // Diagnostic log
    console.log(
      `[search] tier_distribution`,
      JSON.stringify({
        tier0: tier0.length,
        tier1: tier1.length,
        tier2: tier2.length,
        repos: repoResults.length,
        minRelevance,
      }),
    )

    // Combine: [repos] + [tier 0] + [tier 1] + [tier 2]
    const finalResults = [...repoResults, ...tier0, ...tier1, ...tier2]

    const total = finalResults.length
    const safePage = Math.max(1, params.page)
    const start = (safePage - 1) * params.limit
    // Compute per-type counts from the full result set (before pagination)
    const counts = { repos: 0, checkpoints: 0, commits: 0, prs: 0 }
    for (const r of finalResults) {
      if (r.type === "repo") counts.repos++
      else if (r.type === "checkpoint") counts.checkpoints++
      else if (r.type === "commit") counts.commits++
      else if (r.type === "pr") counts.prs++
    }

    const results = finalResults.slice(start, start + params.limit)
    const total_ms = Date.now() - totalStart

    return {
      results,
      total,
      page: safePage,
      timing: { total_ms, keyword_ms: null, embedding_ms, vector_ms, rerank_ms },
      ...(reranked !== undefined && { reranked }),
      counts,
    }
  }

  private async searchUnified(
    userId: string,
    params: SearchParams,
    queryVector: number[],
    searchTypes: string[],
  ): Promise<SearchResult[]> {
    let repos = await getAccessibleReposByUser(this.db, userId)
    if (repos.length === 0) return []

    // Narrow to specific repo if filter is set
    if (params.repo) {
      repos = repos.filter((r) => r.full_name === params.repo)
      if (repos.length === 0) return []
    }

    const chunkLimit = Math.min(Math.max(params.perType.checkpoints * 5, 50), 200)

    // Map search types to doc_types for Turbopuffer filter
    const docTypeMap: Record<string, string[]> = {
      checkpoints: ["checkpoint_chunk", "checkpoint_analysis"],
      commits: ["commit"],
      prs: ["pr"],
    }
    const docTypes = searchTypes.flatMap((t) => docTypeMap[t] ?? [])

    // Group accessible repos by org name for fan-out
    const byOrg = new Map<string, { repoIds: string[]; repoGithubIds: number[] }>()
    for (const repo of repos) {
      const orgName = repo.full_name.split("/")[0] ?? ""
      if (!orgName) continue
      const entry = byOrg.get(orgName) ?? { repoIds: [], repoGithubIds: [] }
      entry.repoIds.push(repo.id)
      entry.repoGithubIds.push(repo.github_id)
      byOrg.set(orgName, entry)
    }

    // Only search orgs explicitly enabled by PostHog flag.
    // In local dev, skip the flag check entirely so all orgs are searchable.
    const orgEntries = [...byOrg.entries()]
    const orgs: Array<[string, { repoIds: string[]; repoGithubIds: number[] }]> = []
    for (const [orgName, data] of orgEntries) {
      if (this.skipFeatureFlags) {
        orgs.push([orgName, data])
        continue
      }

      const flagResult = await isFeatureEnabled(
        this.posthog ?? null,
        "semantic-search-api",
        orgName.toLowerCase(),
      )

      if (flagResult === true) {
        orgs.push([orgName, data])
      }
    }

    // Fan out to org namespaces with concurrency cap
    const allHits: UnifiedSearchRow[] = []

    for (let i = 0; i < orgs.length; i += ORG_QUERY_CONCURRENCY) {
      const slice = orgs.slice(i, i + ORG_QUERY_CONCURRENCY)
      const sliceResults = await Promise.all(
        slice.map(([orgName, { repoGithubIds }]) =>
          searchChunksOrg(
            this.turbopufferApiKey!,
            this.openaiApiKey!,
            orgName,
            params.q,
            repoGithubIds,
            {
              branch: params.branch,
              docTypes: docTypes.length > 0 ? docTypes : undefined,
            },
            chunkLimit,
            this.cache,
            queryVector,
          ),
        ),
      )
      for (const hits of sliceResults) {
        allHits.push(...hits)
      }
    }

    if (allHits.length === 0) return []

    // Group hits by doc_type
    const checkpointHits: UnifiedSearchRow[] = []
    const commitHits: UnifiedSearchRow[] = []
    const prHits: UnifiedSearchRow[] = []

    for (const hit of allHits) {
      if (hit.doc_type === "checkpoint_chunk" || hit.doc_type === "checkpoint_analysis") {
        checkpointHits.push(hit)
      } else if (hit.doc_type === "commit") {
        commitHits.push(hit)
      } else if (hit.doc_type === "pr") {
        prHits.push(hit)
      }
    }

    const bm25HitCount = allHits.filter((h) => h.bm25Rank !== null).length
    const annOnlyCount = allHits.filter((h) => h.bm25Rank === null).length
    console.log(
      `[search] hit_distribution`,
      JSON.stringify({
        total: allHits.length,
        checkpoints: checkpointHits.length,
        commits: commitHits.length,
        prs: prHits.length,
        withBm25: bm25HitCount,
        annOnly: annOnlyCount,
      }),
    )

    const results: SearchResult[] = []

    // ─── Collect IDs for parallel DB hydration ───
    const bestByCheckpoint = new Map<string, UnifiedSearchRow>()
    for (const hit of checkpointHits) {
      if (!hit.checkpoint_id) continue
