function parseStoredCheckpointAnalysis(analysisJson: string | null): {
  analysis: StoredCheckpointAnalysis | null
  error?: string
} {
  if (!analysisJson) return { analysis: null }

  try {
    return { analysis: JSON.parse(analysisJson) as StoredCheckpointAnalysis }
  } catch (error) {
    return {
      analysis: null,
      error: error instanceof Error ? error.message : String(error),
    }
  }
