// Queue message sent after checkpoint data is upserted into PlanetScale
export interface SearchIndexMessage {
  repoId: string
  checkpointIds: string[]
  queuedAt: string
  // Present when triggered by admin reindex — enables stateless progress logging
  reindexId?: string
  reindexMessageIndex?: number
  reindexTotalMessages?: number
}

// Type guard to check if a message is a SearchIndexMessage
export function isSearchIndexMessage(msg: unknown): msg is SearchIndexMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "checkpointIds" in msg &&
    "queuedAt" in msg &&
    typeof (msg as SearchIndexMessage).repoId === "string" &&
    Array.isArray((msg as SearchIndexMessage).checkpointIds)
  )
}

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`[search-index-queue] ${event}`, JSON.stringify(data))
}

// Store a failed search index message after max retries exhausted (dead-letter).
// Stores in KV with 30-day TTL for later investigation and potential re-processing.
async function storeFailedSearchIndexMessage(
  cache: KVNamespace,
  message: SearchIndexMessage,
  error: unknown,
  attempts: number,
): Promise<void> {
  const id = crypto.randomUUID()
  const errorMessage = error instanceof Error ? error.message : String(error)

  const failureData = {
    id,
    repoId: message.repoId,
    checkpointIds: message.checkpointIds,
    reindexId: message.reindexId,
    error_message: errorMessage,
    attempts,
    failed_at: new Date().toISOString(),
    queued_at: message.queuedAt,
  }

  await cache.put(`search_index_dlq:${id}`, JSON.stringify(failureData), {
    expirationTtl: 60 * 60 * 24 * 30, // 30 days
  })

  log("dead_letter", {
    repoId: message.repoId,
    checkpointCount: message.checkpointIds.length,
    attempts,
    error: errorMessage.slice(0, 200),
  })
}

// Ensure transcripts are stored in DB, fetching from GitHub if needed.
// Returns a map of checkpoint_id → stripped JSONL string (session 0).
async function ensureTranscriptsStored(
  db: Db,
  repoId: string,
  repoFullName: string,
  installationId: string | null,
  checkpoints: Array<{
    checkpoint_id: string
    agent: string
    session_count: number
    sessions: SessionInfo[] | null
    storage_version: CheckpointStorageVersion
  }>,
  env: Env,
  batchId: string,
): Promise<Map<string, string | null>> {
  const transcripts = new Map<string, string | null>()
  if (checkpoints.length === 0) return transcripts

  // 1. Try to load transcripts already stored in the DB (written at webhook time).
  const checkpointIds = checkpoints.map((cp) => cp.checkpoint_id)
  const dbRows = await db.checkpoints.getTranscriptBatch(repoId, checkpointIds)
  const missingCheckpoints: typeof checkpoints = []

  for (const row of dbRows) {
    if (row.transcript_stripped) {
      const sessions = parseStoredTranscriptSessions(row.transcript_stripped)
      if (sessions) {
        const primaryJsonl = sessions["0"]?.content
        transcripts.set(row.checkpoint_id, primaryJsonl ?? null)
      } else {
        // Corrupted DB entry — treat as missing so it gets re-fetched
        missingCheckpoints.push(checkpoints.find((cp) => cp.checkpoint_id === row.checkpoint_id)!)
      }
    } else {
      missingCheckpoints.push(checkpoints.find((cp) => cp.checkpoint_id === row.checkpoint_id)!)
    }
  }

  // Also include any checkpoint_ids not returned by the DB at all
  const returnedIds = new Set(dbRows.map((r) => r.checkpoint_id))
  for (const cp of checkpoints) {
    if (!returnedIds.has(cp.checkpoint_id) && !transcripts.has(cp.checkpoint_id)) {
      missingCheckpoints.push(cp)
    }
  }

  // 2. Fetch missing transcripts from GitHub as a fallback.
  if (missingCheckpoints.length > 0 && installationId) {
    try {
      const githubInstallationId = await db.installations.getGithubId(installationId)
      if (!githubInstallationId) {
        log("transcript_no_github_installation", { batchId, repoId, installationId })
        return transcripts
      }

      const token = await getInstallationToken(
        githubInstallationId,
        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
        env.ENTIRE_CACHE,
      )

      const dbUpdates: Array<{
        checkpoint_id: string
        transcript_stripped: string
        deadSessionIndices?: number[]
      }> = []
      const deadOnlyUpdates: Array<{ checkpoint_id: string; deadSessionIndices: number[] }> = []
      const repoProvider = await pickRepoReadProvider(env, repoFullName)

      for (let i = 0; i < missingCheckpoints.length; i += TRANSCRIPT_CONCURRENCY) {
        const transcriptBatch = missingCheckpoints.slice(i, i + TRANSCRIPT_CONCURRENCY)
        const results = await Promise.all(
          transcriptBatch.map((cp) =>
            fetchAndStripTranscripts(
              repoProvider,
              repoFullName,
              cp.checkpoint_id,
              cp.session_count ?? 1,
              cp.agent,
              (cp.sessions as SessionInfo[] | null) ?? null,
              cp.storage_version,
              token,
            ),
          ),
        )

        for (let j = 0; j < results.length; j++) {
          const cp = transcriptBatch[j]
          const result = results[j]
          if (!result) continue
          const { sessions, hadTransientError } = result
          const sessionCount = cp.session_count ?? 1
          const hasContent = Object.keys(sessions).length > 0
          const deadIndices = hadTransientError
            ? undefined
            : computeDeadSessionIndices(sessionCount, sessions)
          if (hasContent) {
            dbUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              transcript_stripped: serializeStoredTranscriptSessions(sessions),
              deadSessionIndices: deadIndices,
            })

            const primaryJsonl = sessions["0"]?.content
            transcripts.set(cp.checkpoint_id, primaryJsonl ?? null)
          } else if (deadIndices && deadIndices.length > 0) {
            deadOnlyUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              deadSessionIndices: deadIndices,
            })
          }
        }
      }

      if (dbUpdates.length > 0) {
        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates)
        if (stored > 0) {
          const updatedCheckpointIds = new Set(dbUpdates.map((update) => update.checkpoint_id))
          const touched = missingCheckpoints.filter((cp) =>
            updatedCheckpointIds.has(cp.checkpoint_id),
          )
          await invalidateCheckpointCaches(env.ENTIRE_CACHE, repoFullName, touched)
        }
        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length })
      }
      if (deadOnlyUpdates.length > 0) {
        await db.checkpoints.updateDeadSessionIndicesBatch(repoId, deadOnlyUpdates)
      }
    } catch (err) {
      log("transcript_fetch_error", {
        batchId,
        repoId,
        error: err instanceof Error ? err.message : String(err),
      })
    }
  }

  return transcripts
}

// Fetch all checkpoint IDs for a repo, used when reindexing an entire repo.
export async function getAllCheckpointIdsForRepo(env: Env, repoId: string): Promise<string[]> {
  const kysely = getKysely(env)
  const rows = await kysely
    .selectFrom("repo_checkpoints")
    .select("checkpoint_id")
    .where("repo_id", "=", repoId)
    .execute()
  return rows.map((r) => r.checkpoint_id)
}

// Process a single batch of checkpoint IDs: fetch details, transcripts, build chunks, and index.
export async function processCheckpointBatch(
  db: Db,
  env: Env,
  repo: Repo,
  repoId: string,
  checkpointIds: string[],
  batchId: string,
): Promise<number> {
  const checkpoints = await db.checkpoints.getForSearchIndexing(repoId, checkpointIds)
  if (checkpoints.length === 0) return 0

  const checkpointRepoName = getCheckpointRepoName(repo)

  const transcriptsPromise = ensureTranscriptsStored(
    db,
    repoId,
    checkpointRepoName,
    repo.installation_id,
    checkpoints.map((cp) => ({
      checkpoint_id: cp.checkpoint_id,
      agent: cp.agent ?? LEGACY_FALLBACK_AGENT_NAME,
      session_count: cp.session_count ?? 1,
      sessions: (cp.sessions as SessionInfo[] | null) ?? null,
      storage_version: cp.storage_version ?? CHECKPOINT_V1_STORAGE_VERSION,
    })),
    env,
    batchId,
  )
  const analysesPromise = db.analyses.getByCheckpointIds(repoId, checkpointIds)
  const [transcripts, analysisRows] = await Promise.all([transcriptsPromise, analysesPromise])

  const analysesByCheckpointId = new Map<string, StoredCheckpointAnalysis>()
  for (const row of analysisRows) {
    if (row.status !== "complete") continue
    const { analysis, error } = parseStoredCheckpointAnalysis(row.analysis_json)
    if (error) {
      log("analysis_parse_error", {
        batchId,
        repoId,
        checkpointId: row.checkpoint_id,
        analysisId: row.id,
        error,
      })
    }
    if (analysis) {
      analysesByCheckpointId.set(row.checkpoint_id, analysis)
    }
  }

  // Build chunks for each checkpoint from its transcript (session 0),
  // falling back to a single metadata chunk when no transcript is available.
  const checkpointWithChunks = checkpoints.map((cp) => {
    const jsonl = transcripts.get(cp.checkpoint_id) ?? null
    let chunks: SearchChunk[] = []

    if (jsonl) {
      try {
        const { messages } = parseCheckpointTranscriptForIndexing(
          jsonl,
          cp.agent ?? LEGACY_FALLBACK_AGENT_NAME,
          cp.storage_version ?? CHECKPOINT_V1_STORAGE_VERSION,
        )
        const sessions = (cp.sessions as SessionInfo[] | null) ?? null
        const uuidBoundary = sessions?.[0]?.transcriptIdentifierAtStart ?? null
        const filtered = filterRelevantMessages(messages, uuidBoundary)
        chunks = chunkTranscript(filtered, cp.checkpoint_id)
      } catch {
        // fall through to metadata-only fallback below
      }
    }

    const analysis = analysesByCheckpointId.get(cp.checkpoint_id)

    if (chunks.length === 0) {
      // Fallback: single chunk from prompt + commit + files (no transcript)
      const analysisText = analysis ? buildCheckpointAnalysisRetrievalSummary(analysis) : null
      const text = buildSearchText({
        prompt: cp.prompt,
        commit_message: cp.commit_message,
        files_touched: cp.files_touched,
        analysis: analysisText || null,
      })
      if (text.trim()) {
        chunks = [
          {
            chunkId: makeChunkId(cp.checkpoint_id, 0),
            checkpointId: cp.checkpoint_id,
            chunkIndex: 0,
            text,
            turnStart: 0,
            turnEnd: 0,
            tokenEstimate: Math.ceil(text.length / 4),
            chunkVersion: CHUNK_VERSION,
          },
        ]
      }
    }
    if (analysis) {
      const analysisChunks = buildCheckpointAnalysisBlockChunks(
        analysis,
        cp.checkpoint_id,
        chunks.length,
      )
      chunks = [...chunks, ...analysisChunks]
    }

    return {
      checkpoint_id: cp.checkpoint_id,
      branch: cp.branch,
      agent: cp.agent,
      commit_author_username: cp.commit_author_username,
      created_at: cp.created_at,
      commit_sha: cp.commit_sha,
      commit_message: cp.commit_message,
      prompt: cp.prompt,
      files_touched: cp.files_touched,
      chunks,
    }
  })

  // Pass org info so chunks are dual-written to the org-level namespace.
  // Org name is derived from full_name (e.g., "acme/backend-api" → "acme").
  const orgName = repo.full_name.split("/")[0]
  const orgInfo: OrgInfo | undefined = orgName
    ? { orgName, repoGithubId: repo.github_id }
    : undefined

  return indexCheckpointChunks(
    env.TURBOPUFFER_API_KEY!,
    env.OPENAI_API_KEY!,
    repo.github_id,
    checkpointWithChunks,
    orgInfo,
  )
}

