export async function indexCheckpointChunks(
  turbopufferApiKey: string,
  openaiApiKey: string,
  githubId: number,
  checkpoints: CheckpointChunkInput[],
  orgInfo?: OrgInfo,
): Promise<number> {
  // Use org-level namespace when orgInfo is provided; fall back to per-repo for legacy callers.
  const namespace = orgInfo
    ? `checkpoints-v2-org-${orgInfo.orgName}`
    : `checkpoints-v2-gh-${githubId}`
  const startMs = Date.now()

  // Flatten all chunks across all checkpoints
  const allItems: Array<{ chunk: SearchChunk; checkpoint: CheckpointChunkInput }> = []
  for (const cp of checkpoints) {
    for (const chunk of cp.chunks) {
      allItems.push({ chunk, checkpoint: cp })
    }
  }

  if (allItems.length === 0) {
    console.log(
      `[search-index] chunk_index_skipped`,
      JSON.stringify({
        namespace,
        checkpointCount: checkpoints.length,
        reason: "no_chunks",
      }),
    )
    return 0
  }

  console.log(
    `[search-index] chunk_index_started`,
    JSON.stringify({
      namespace,
      checkpointCount: checkpoints.length,
      chunkCount: allItems.length,
      // Checkpoints with >1 chunk had a transcript; single-chunk ones are metadata-only fallbacks
      withTranscript: checkpoints.filter((cp) => cp.chunks.length > 1).length,
    }),
  )

  // Compute numeric surrogate IDs and detect within-batch hash collisions
  const numericIds = await Promise.all(allItems.map((item) => chunkIdToNumeric(item.chunk.chunkId)))

  const seenIds = new Map<number, string>()
  for (let i = 0; i < numericIds.length; i++) {
    const numId = numericIds[i]
    const chunkId = allItems[i].chunk.chunkId
    if (seenIds.has(numId)) {
      console.error(
        `[search-index] chunk_id_collision`,
        JSON.stringify({
          namespace,
          numericId: numId,
          chunkId1: seenIds.get(numId),
          chunkId2: chunkId,
        }),
      )
    }
    seenIds.set(numId, chunkId)
  }

  // Embed and upsert in sub-batches to stay under OpenAI's 300K token limit
  // and reduce Worker memory pressure.
  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`
  let totalEmbedMs = 0

  for (let batchStart = 0; batchStart < allItems.length; batchStart += UPSERT_BATCH_SIZE) {
    const batchEnd = Math.min(batchStart + UPSERT_BATCH_SIZE, allItems.length)
    const batchItems = allItems.slice(batchStart, batchEnd)
    const batchNumericIds = numericIds.slice(batchStart, batchEnd)

    const texts = batchItems.map((item) => item.chunk.text.slice(0, MAX_EMBEDDING_CHARS))
    const batchEmbedStart = Date.now()
    const embeddings = await embedTexts(openaiApiKey, texts)
    totalEmbedMs += Date.now() - batchEmbedStart

    const upserts = batchItems.map(({ chunk, checkpoint }, i) => {
      const filesTouchedStr = checkpoint.files_touched?.join(" ") ?? ""
      const titleText = [checkpoint.prompt, checkpoint.commit_message]
        .filter(Boolean)
        .join("\n")
        .slice(0, 500)
      const metaText = [checkpoint.branch, filesTouchedStr, checkpoint.commit_author_username]
        .filter(Boolean)
        .join(" ")
      return {
        id: batchNumericIds[i],
        vector: embeddings[i],
        attributes: {
          // Chunk identity
          chunk_id: chunk.chunkId,
          doc_id: chunk.chunkId,
          doc_type: "checkpoint_chunk",
          checkpoint_id: chunk.checkpointId,
          chunk_index: chunk.chunkIndex,
          chunk_version: chunk.chunkVersion,
          // ACL + filtering
          repo_github_id: orgInfo?.repoGithubId ?? githubId,
          branch: checkpoint.branch,
          agent: checkpoint.agent,
          author: checkpoint.commit_author_username,
          created_at: checkpoint.created_at,
          commit_sha: checkpoint.commit_sha,
          // Multi-field BM25
          title_text: truncateToBytes(titleText, MAX_FILTERABLE_BYTES),
          meta_text: truncateToBytes(metaText, MAX_FILTERABLE_BYTES),
          chunk_text: truncateToBytes(chunk.text, MAX_TEXT_BYTES),
        },
      }
    })

    const resp = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${turbopufferApiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        upserts,
        distance_metric: "cosine_distance",
        schema: SEARCH_SCHEMA,
      }),
    })

    if (!resp.ok) {
      const errText = await resp.text().catch(() => "")
      console.log(
        `[search-index] chunk_index_error`,
        JSON.stringify({
          namespace,
          durationMs: Date.now() - startMs,
          status: resp.status,
          error: errText.slice(0, 200),
          batch: `${batchStart}-${batchEnd}/${allItems.length}`,
        }),
      )
      throw new Error(`Turbopuffer chunk upsert failed (${resp.status}): ${errText}`)
    }
  }

  console.log(
    `[search-index] chunk_index_complete`,
    JSON.stringify({
      namespace,
      durationMs: Date.now() - startMs,
      embedDurationMs: totalEmbedMs,
      chunkCount: allItems.length,
      checkpointCount: checkpoints.length,
    }),
  )

  return allItems.length
}

