 *
 * Callers should treat `undefined` as "not enabled" — when flag definitions aren't
 * available, we prefer skipping indexing over accidentally indexing the wrong orgs.
 */
export async function isFeatureEnabled(
  client: PostHog | null,
  flag: FeatureFlagKey,
  owner: string,
  repo?: string,
): Promise<boolean | undefined> {
  if (!client) return undefined

  try {
    const personProperties: Record<string, string> = { owner }
    if (repo) {
      personProperties.repo = repo
    }

    const result = await client.getFeatureFlag(flag, owner, {
      personProperties,
      onlyEvaluateLocally: true,
    })

    // undefined = flag definitions not loaded yet (cold start / empty KV cache)
    if (result === undefined) return undefined

    return result === true
  } catch {
    return undefined
  }
}

